CREATE DEFINER=`root`@`localhost` FUNCTION `fn_can_teacher_grade_subject`(`p_teacher_id` INT, `p_subject_id` INT, `p_grade_level` INT, `p_section` VARCHAR(50), `p_school_year_id` INT) RETURNS tinyint(1)
    READS SQL DATA
    DETERMINISTIC
BEGIN
    DECLARE v_can_grade TINYINT(1);
    
    
    SELECT COUNT(*) INTO v_can_grade
    FROM subject_teacher_assignments
    WHERE teacher_id = p_teacher_id
    AND subject_id = p_subject_id
    AND grade_level = p_grade_level
    AND section = p_section
    AND school_year_id = p_school_year_id;
    
    RETURN v_can_grade > 0;
END ;;
